import json

fpath = '/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0513-6-projects-faith-evidence-ie/596d8411-63f5-4757-a2a4-2c57b1fcaba0/tool-results/mcp-agent-ml-research-read_registry-1779141732674.txt'

with open(fpath, 'r') as f:
    raw = json.load(f)

result_str = raw.get('result', raw)
if isinstance(result_str, str):
    data = json.loads(result_str)
else:
    data = result_str

experiments = data['data']['experiments']

# Find all 4B eval experiments and dump ALL nested data to find metrics
for exp_id, exp in sorted(experiments.items()):
    is_4b = False
    cmd = exp.get('spec', {}).get('command', '')
    hypothesis = exp.get('hypothesis', '')
    model_name = exp.get('spec', {}).get('model_name', '')
    checks = [cmd, hypothesis, model_name, exp_id]
    for c in checks:
        if c and ('4b' in c.lower() or '4B' in c or 'Qwen3-4B' in c):
            is_4b = True
            break
    if not is_4b:
        continue
    is_eval = 'eval' in exp_id.lower() or ('eval' in cmd.lower() and 'inference' in cmd.lower()) or 'eval' in hypothesis.lower()
    if not is_eval:
        continue

    # Deep search for any key containing 'f1' or 'metric' in all nested dicts
    def find_metrics(obj, path=''):
        results = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_path = f'{path}.{k}' if path else k
                if any(kw in k.lower() for kw in ['f1', 'metric', 'score', 'precision', 'recall', 'accuracy', 'edcr']):
                    results.append((new_path, v))
                results.extend(find_metrics(v, new_path))
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                results.extend(find_metrics(v, f'{path}[{i}]'))
        return results

    metrics_found = find_metrics(exp)
    if metrics_found:
        print(f'{exp_id}:')
        for path, val in metrics_found:
            print(f'  {path} = {val}')
